function update(dt){if(cafeAnyModalOpen()){keys.clear();player.moving=false;cafeMobileState.route=[];return;}if(window.__cafeSandboxModalOpen)window.__cafeSandboxModalOpen=false;updateNpc(dt);if(!testMode||!ready)return;let dx=0,dy=0;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;
if(cafeMobileMode()){
 const ms=cafeMobileState;
 if(Math.hypot(ms.stickX,ms.stickY)>.12){dx+=ms.stickX;dy+=ms.stickY;ms.route=[]}
 else if(ms.route.length){
  const dest=ms.route[0],dist=Math.hypot(dest.x-player.x,dest.y-player.y);
  if(dist<Math.max(8,player.speed*dt*1.25)){ms.route.shift()}
  if(ms.route.length){const aim=ms.route[0];dx+=(aim.x-player.x)/Math.max(1,Math.hypot(aim.x-player.x,aim.y-player.y));dy+=(aim.y-player.y)/Math.max(1,Math.hypot(aim.x-player.x,aim.y-player.y))}
 }
}
player.moving=Boolean(dx||dy);if(!player.moving){activeInteraction=nearby();return}const len=Math.hypot(dx,dy);dx/=len;dy/=len;let nx=clamp(player.x+dx*player.speed*dt,75,1800),ny=clamp(player.y+dy*player.speed*dt,165,1320);if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;player.face=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');player.elapsed+=dt;activeInteraction=nearby();}
function nearby(){let best=null,bestD=Infinity;for(const z of interactions){if(z.trigger==='click')continue;if(z.approach&&insideShape({x:player.x,y:player.y},z.approach)){const b=z.click;const cx=b.shape==='polygon'?b.points.reduce((a,p)=>a+p.x,0)/b.points.length:b.x+b.w/2;const cy=b.shape==='polygon'?b.points.reduce((a,p)=>a+p.y,0)/b.points.length:b.y+b.h/2;const d=Math.hypot(cx-player.x,cy-player.y);if(d<bestD){best=z;bestD=d}}}return best}
function point(e){const r=canvas.getBoundingClientRect();return {x:Math.round((e.clientX-r.left)*canvas.width/r.width),y:Math.round((e.clientY-r.top)*canvas.height/r.height)}}
function alphaHit(o,p){const im=images[o.asset];if(!im)return false;let x=Math.floor((p.x-o.x)/(o.scale||1)),y=Math.floor((p.y-o.y)/(o.scale||1));if(x<0||y<0||x>=im.width||y>=im.height)return false;let data=alphaPixels.get(o.asset);if(!data){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const cc=c.getContext('2d',{willReadFrequently:true});cc.drawImage(im,0,0);data=cc.getImageData(0,0,c.width,c.height).data;alphaPixels.set(o.asset,data)}return data[(y*im.width+x)*4+3]>24}
const alphaPixels=new Map();
const interactionCursor='pointer';
let hoveredHotspot=null;
let hoverPointer=null;
/* Sparkling pointer state is drawn directly on the game canvas so it always
   stays aligned to the interactive artwork even when the editor pane resizes. */
function drawHotspotHover(){
 if(!testMode||!hoveredHotspot||!hoverPointer||window.__cafeSandboxModalOpen)return;
 const t=performance.now()/1000,cx=Math.round(hoverPointer.x),cy=Math.round(hoverPointer.y);
 ctx.save();
 // Five equal-sized solid pixel + sparkles orbit the pointer at evenly spaced angles.
 const count=5,radius=25,unit=3,arm=2;
 function pixelPlus(x,y){
  const x0=Math.round(x/unit)*unit,y0=Math.round(y/unit)*unit;
  ctx.fillStyle='#32134f';
  ctx.fillRect(x0-unit,y0-(arm+1)*unit,unit*3,(arm*2+3)*unit);
  ctx.fillRect(x0-(arm+1)*unit,y0-unit,(arm*2+3)*unit,unit*3);
  ctx.fillStyle='#9a4dec';
  ctx.fillRect(x0,y0-arm*unit,unit,(arm*2+1)*unit);
  ctx.fillRect(x0-arm*unit,y0,unit*(arm*2+1),unit);
 }
 for(let i=0;i<count;i++){
  const angle=t*1.65+i*Math.PI*2/count;
  pixelPlus(cx+Math.cos(angle)*radius,cy+Math.sin(angle)*radius);
 }
 ctx.restore();
}

function pickFurniture(p){return objects.filter(o=>o.environment!=='frame').sort((a,b)=>(b.zIndex||0)-(a.zIndex||0)||((b.baseY??(b.y+(images[b.asset]?.height||0)*(b.scale||1)))-(a.baseY??(a.y+(images[a.asset]?.height||0)*(a.scale||1))))).find(o=>alphaHit(o,p))||null}
function pickZone(p){if(mode==='collision')return [...collisions].reverse().find(z=>insideShape(p,z));if(mode==='interaction')return [...interactions].reverse().find(z=>insideShape(p,z.approach)||insideShape(p,z.click));if(mode==='character')return [...characters].reverse().find(c=>{if(c.sprite?.startsWith('sheet:')){const sh=customCharacterSheets[c.sprite.slice(6)],im=images['sprite-'+c.sprite.slice(6)];if(sh&&im){const w=im.width/(sh.cols||4)*(c.scale||.6),h=im.height/(sh.rows||3)*(c.scale||.6);return p.x>=c.x-w/2&&p.x<=c.x+w/2&&p.y>=c.y-h&&p.y<=c.y+12}}return Math.hypot(c.x-p.x,c.y-p.y)<55;});return pickFurniture(p)}
function moveShape(s,dx,dy){if(s.shape==='polygon')s.points.forEach(p=>{p.x+=dx;p.y+=dy});else{s.x+=dx;s.y+=dy}}
// Resize and vertex edit helpers: the handles operate in original 1874×1398 canvas coordinates.
let activeInteractionPart='click';
function editedShape(){if(!selected)return null;if(mode==='collision')return selected;if(mode==='interaction'){return activeInteractionPart==='approach'?(selected.approach||null):selected.click}return null}
function boxHandles(s){const x=s.x,y=s.y,w=s.w,h=s.h;return [
 {name:'nw',x,y},{name:'n',x:x+w/2,y},{name:'ne',x:x+w,y},
 {name:'e',x:x+w,y:y+h/2},{name:'se',x:x+w,y:y+h},
 {name:'s',x:x+w/2,y:y+h},{name:'sw',x,y:y+h},{name:'w',x,y:y+h/2}];}
function getHandles(s){return !s?[]:s.shape==='polygon'?s.points.map((p,i)=>({name:'vertex',index:i,x:p.x,y:p.y})):boxHandles(s)}
function hitHandle(p){if(testMode||!selected||(mode!=='collision'&&mode!=='interaction'))return null;
 const s=editedShape();if(!s)return null;const handles=getHandles(s);
 // generous hit target for handles despite responsive game scaling
 for(const h of [...handles].reverse())if(Math.hypot(p.x-h.x,p.y-h.y)<=17)return {handle:h,shape:s};return null;}
function updateResize(d,p){const s=d.shape;if(s.shape==='polygon'){
  const v=s.points[d.handle.index];v.x=p.x;v.y=p.y;return;}
 const {x,y,w,h}=d.original, name=d.handle.name,min=8;
 let l=x,t=y,r=x+w,b=y+h;
 if(name.includes('w'))l=Math.min(r-min,p.x);
 if(name.includes('e'))r=Math.max(l+min,p.x);
 if(name.includes('n'))t=Math.min(b-min,p.y);
 if(name.includes('s'))b=Math.max(t+min,p.y);
 s.x=Math.round(l);s.y=Math.round(t);s.w=Math.round(r-l);s.h=Math.round(b-t);
}
function drawResizeHandles(){if(testMode||!showZones||!selected||(mode!=='collision'&&mode!=='interaction'))return;
 const s=editedShape();if(!s)return;
 ctx.save();ctx.setLineDash([]);ctx.lineWidth=3;ctx.font='bold 19px system-ui';
 for(const h of getHandles(s)){ctx.beginPath();ctx.arc(h.x,h.y,9,0,Math.PI*2);ctx.fillStyle='#fff9e6';ctx.fill();ctx.strokeStyle='#173a31';ctx.stroke();}
 if(s.shape==='polygon'){
   // Draw small node indices to clarify which point is being edited.
   getHandles(s).forEach(h=>{ctx.fillStyle='#173a31';ctx.fillText(String(h.index+1),h.x+12,h.y-11)});
 }
 ctx.restore();}

function shiftLinked(owner,dx,dy){for(const c of collisions)if(c.linkedTo===owner.id)moveShape(c,dx,dy);for(const z of interactions)if(z.linkedTo===owner.id){moveShape(z.click,dx,dy);if(z.approach)moveShape(z.approach,dx,dy)}}
function newShape(p,q,shape='rectangle'){return {shape,x:Math.min(p.x,q.x),y:Math.min(p.y,q.y),w:Math.max(4,Math.abs(q.x-p.x)),h:Math.max(4,Math.abs(q.y-p.y))}}
