async function addFurnitureFiles(files,location){
 if(testMode||uploadBusy)return;
 const pngs=Array.from(files||[]).filter(f=>f.type==='image/png'||f.name.toLowerCase().endsWith('.png'));
 if(!pngs.length){summary('Drop a PNG image to add furniture.');return;}
 uploadBusy=true;
 try{
  checkpoint();mode='furniture';tool='select';
  for(let i=0;i<pngs.length;i++){
   const file=pngs[i];if(file.size>20*1024*1024)throw Error(file.name+' exceeds 20 MB PNG limit');
   const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read '+file.name));reader.readAsDataURL(file)});
   if(!/^data:image\/png;base64,/i.test(data))throw Error(file.name+' is not a PNG image');
   const key='uploaded-'+makeId('asset')+'.png';const im=await loadPNGAsset(key,data);customAssets[key]=data;
   const x=Math.round((location?.x??937)-im.width/2+i*14),y=Math.round((location?.y??700)-im.height/2+i*14);
   const item={id:makeId('furniture'),asset:key,label:file.name.replace(/\.png$/i,''),x,y,baseY:y+im.height,zIndex:2,scale:1};
   objects.push(item);selected=item;
  }
  panel();summary('Added '+pngs.length+' PNG asset'+(pngs.length===1?'':'s')+'. Drag to position or edit scale/Z-index. Export JSON to save the images.');
 }catch(err){summary('Upload failed: '+err.message)}finally{uploadBusy=false;uploadInput.value=''}
}
