const frameUploadInput=document.createElement('input');frameUploadInput.type='file';frameUploadInput.accept='image/png,.png';frameUploadInput.multiple=true;frameUploadInput.hidden=true;document.body.appendChild(frameUploadInput);
let pendingFrameSlot=null;
const guessedSlotFromName=name=>{
 const n=name.toLowerCase().replace(/\.png$/,'').replace(/[^a-z0-9]+/g,'_');
 let dir=null;
 if(/(^|_)(front|forward|down)(_|$)/.test(n))dir='down';
 else if(/(^|_)(back|backward|up)(_|$)/.test(n))dir='up';
 else if(/(^|_)(right)(_|$)/.test(n))dir='right';
 else if(/(^|_)(left)(_|$)/.test(n))dir='left';
 if(!dir)return null;
 if(/(sit|seat)/.test(n))return dir+'_sit';
 if(/(step_?b|walk_?b|walk_?2|step_?2)/.test(n))return dir+'_stepB';
 if(/(step_?a|walk_?a|walk_?1|step_?1)/.test(n))return dir+'_stepA';
 if(/(idle|stand|still)/.test(n))return dir+'_idle';
 return null;
};
async function addIndividualSpriteFiles(files,position,slot=null){
 if(testMode)return;
 const pngs=Array.from(files||[]).filter(f=>f.type==='image/png'||/\.png$/i.test(f.name));
 if(!pngs.length){summary('Please upload transparent PNG character frames.');return;}
 const target=(selected?.sprite?.startsWith('frames:')?selected:null);
 try{
   const readFiles=[];
   for(const file of pngs){
     if(file.size>24*1024*1024)throw Error(file.name+' exceeds 24 MB');
     const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Cannot read '+file.name));r.readAsDataURL(file)});
     if(!/^data:image\/png;base64,/i.test(src))throw Error('Not a PNG: '+file.name);
     readFiles.push({name:file.name,src});
   }
   checkpoint();mode='character';tool='select';
   let ch=target;
   if(!ch){
     const id=makeId('frames');customCharacterFrames[id]={name:pngs[0].name.replace(/\.png$/i,''),files:{},frames:{}};
     ch={id:makeId('npc'),label:pngs.length===1?pngs[0].name.replace(/\.png$/i,''):'New character',sprite:'frames:'+id,x:position?.x??970,y:position?.y??940,face:'down',sitFace:'down',posture:'standing',scale:.6,zIndex:4,visible:true,movable:false,path:{enabled:false,playing:false,loop:'repeat',waypoints:[]}};
     characters.push(ch);
   }
   const id=ch.sprite.slice(7),collection=customCharacterFrames[id];
   for(let i=0;i<readFiles.length;i++){
     const item=readFiles[i],key=makeId('frame');
     collection.files[key]=item;
     await loadPNGAsset('frames-'+id+'-'+key,item.src);
     const assign=(i===0&&slot)||guessedSlotFromName(item.name);
     if(assign)collection.frames[assign]=key;
     else if(!collection.frames.down_idle)collection.frames.down_idle=key;
   }
   selected=ch;selectedWaypoint=-1;panel();
   summary('Imported '+readFiles.length+' PNG frame(s). Assign each direction and pose from the dropdowns, then export level JSON.');
 }catch(err){summary('Sprite upload failed: '+err.message)}finally{frameUploadInput.value='';pendingFrameSlot=null}
}
