 if($('furnitureList'))$('furnitureList').onchange=e=>{selected=objects.find(o=>o.id===e.target.value)||null;panel()};
 if($('deleteFurniture'))$('deleteFurniture').onclick=()=>deleteFurniture(selected);

 if($('pathMode'))$('pathMode').onclick=()=>{tool=tool==='path'?'select':'path';selectedWaypoint=-1;panel()};
if($('charPosture')){$('charPosture').value=selected.posture||'standing';$('charPosture').onchange=e=>{checkpoint();selected.posture=e.target.value;if(selected.posture==='sitting'){selected.path=selected.path||{enabled:true,loop:'repeat',playing:true,waypoints:[]};selected.path.playing=false;selected.face='down';}else if(selected.path){selected.path.playing=true;}panel()}}
 if($('charSitFace')){$('charSitFace').value=selected.sitFace||'down';$('charSitFace').onchange=e=>{checkpoint();selected.sitFace=e.target.value;panel()}}
 if($('uploadFrames'))$('uploadFrames').onclick=()=>{pendingFrameSlot=null;frameUploadInput.click()};
 if($('addMoreFrames'))$('addMoreFrames').onclick=()=>{pendingFrameSlot=null;frameUploadInput.click()};
 options.querySelectorAll('[data-frame-slot]').forEach(el=>el.onchange=()=>{checkpoint();const set=customCharacterFrames[selected.sprite.slice(7)];set.frames[el.dataset.frameSlot]=el.value||null;panel()});
