 if($('uploadSprite'))$('uploadSprite').onclick=()=>spriteUploadInput.click();
 if($('characterList'))$('characterList').onchange=e=>{selected=characters.find(ch=>ch.id===e.target.value)||null;selectedWaypoint=-1;panel()};
 if($('spritePose')){$('spritePose').value=selected.posture||'standing';$('spritePose').onchange=e=>{checkpoint();selected.posture=e.target.value;if(selected.path){selected.path.playing=selected.posture==='standing'}resetNpcRuntime();panel()}}
 if($('spriteSitFace')){$('spriteSitFace').value=selected.sitFace||'down';$('spriteSitFace').onchange=e=>{checkpoint();selected.sitFace=e.target.value;panel()}}
 if($('spriteCols'))$('spriteCols').onchange=e=>changeSpriteGrid(selected,'cols',+e.target.value);
 if($('spriteRows'))$('spriteRows').onchange=e=>changeSpriteGrid(selected,'rows',+e.target.value);
 options.querySelectorAll('[data-sprite-slot]').forEach(el=>el.onchange=()=>{checkpoint();const sh=customCharacterSheets[selected.sprite.slice(6)];sh.frames[el.dataset.spriteSlot]=el.value===''?null:Number(el.value);panel()});
 if($('spriteSheetPreview')){const el=$('spriteSheetPreview'),sh=customCharacterSheets[selected.sprite.slice(6)],im=images['sprite-'+selected.sprite.slice(6)];if(sh&&im){const c=el.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,el.width,el.height);c.drawImage(im,0,0,el.width,el.height);c.strokeStyle='#e9c56f';c.lineWidth=1;for(let x=1;x<sh.cols;x++){c.beginPath();c.moveTo(x*el.width/sh.cols,0);c.lineTo(x*el.width/sh.cols,el.height);c.stroke()}for(let y=1;y<sh.rows;y++){c.beginPath();c.moveTo(0,y*el.height/sh.rows);c.lineTo(el.width,y*el.height/sh.rows);c.stroke()}}}
 if($('sheetPathEnabled'))$('sheetPathEnabled').onchange=e=>{checkpoint();selected.path.enabled=e.target.checked;selected.path.playing=e.target.checked;resetNpcRuntime();panel()};
 if($('sheetPathLoop')){$('sheetPathLoop').value=selected.path?.loop||'repeat';$('sheetPathLoop').onchange=e=>{checkpoint();selected.path.loop=e.target.value;panel()}}
 if($('sheetAddWaypoint'))$('sheetAddWaypoint').onclick=()=>{checkpoint();const p=selected.path.waypoints,last=p.at(-1)||selected;p.push({x:last.x+65,y:last.y,face:'auto',duration:2,wait:1});selectedWaypoint=p.length-1;resetNpcRuntime();panel()};
 if($('sheetRestartPath'))$('sheetRestartPath').onclick=()=>{selected.path.playing=true;resetNpcRuntime();panel()};
 if($('sheetWaypointControls')&&selected.path){const points=selected.path.waypoints;const node=points[selectedWaypoint];$('sheetWaypointControls').innerHTML='<label>Choose route node<select id="sheetNode"><option value="-1">Select a waypoint…</option>'+points.map((n,i)=>`<option value="${i}">Node ${i+1} — (${Math.round(n.x)}, ${Math.round(n.y)})</option>`).join('')+'</select></label>'+(node?`<div class="row"><label>X<input data-sheet-way="x" type="number" value="${Math.round(node.x)}"></label><label>Y<input data-sheet-way="y" type="number" value="${Math.round(node.y)}"></label></div><div class="row"><label>Travel seconds<input data-sheet-way="duration" type="number" min="0.1" step="0.1" value="${node.duration}"></label><label>Pause seconds<input data-sheet-way="wait" type="number" min="0" step="0.1" value="${node.wait}"></label></div><label>Travel direction<select data-sheet-way="face"><option value="auto">Automatic</option><option value="down">Down</option><option value="up">Up</option><option value="right">Right</option><option value="left">Left</option></select></label><button id="sheetDeleteNode">Remove node</button>`:'');if($('sheetNode')){$('sheetNode').value=String(selectedWaypoint);$('sheetNode').onchange=e=>{selectedWaypoint=+e.target.value;panel()}}if(node){for(const el of $('sheetWaypointControls').querySelectorAll('[data-sheet-way]')){if(el.dataset.sheetWay==='face')el.value=node.face||'auto';el.onchange=()=>{checkpoint();node[el.dataset.sheetWay]=el.dataset.sheetWay==='face'?el.value:Number(el.value);resetNpcRuntime();panel()}}$('sheetDeleteNode').onclick=()=>{checkpoint();points.splice(selectedWaypoint,1);selectedWaypoint=-1;resetNpcRuntime();panel()}}}
 if($('pathEnabled'))$('pathEnabled').onchange=e=>{checkpoint();selected.path.enabled=e.target.checked;resetNpcRuntime();panel()};
 if($('pathLoop')){$('pathLoop').value=selected.path.loop||'repeat';$('pathLoop').onchange=e=>{checkpoint();selected.path.loop=e.target.value;panel()}}
 if($('addWaypoint'))$('addWaypoint').onclick=()=>{checkpoint();const p=selected.path.waypoints;const last=p.at(-1)||{x:selected.x,y:selected.y};p.push({x:last.x+65,y:last.y,face:'auto',duration:2,wait:.5});selectedWaypoint=p.length-1;resetNpcRuntime();panel()};
 if($('clearWaypoints'))$('clearWaypoints').onclick=()=>{checkpoint();selected.path.waypoints=[];selectedWaypoint=-1;resetNpcRuntime();panel()};
 if($('restartPath'))$('restartPath').onclick=()=>{selected.path.playing=true;resetNpcRuntime();panel()};
 if($('waypointControls')&&selected.path){const p=selected.path.waypoints, wp=p[selectedWaypoint];
 $('waypointControls').innerHTML='<label>Choose walking path node<select id="waypointDropdown"><option value="-1">Select a node…</option>'+p.map((node,i)=>'<option value="'+i+'">Node '+(i+1)+' — ('+Math.round(node.x)+', '+Math.round(node.y)+')</option>').join('')+'</select></label><div class="muted">Waypoints: '+p.length+' · '+(selectedWaypoint<0?'Choose a node above or click a numbered marker on the canvas.':'Editing waypoint '+(selectedWaypoint+1))+'</div>'+
 (wp?`<div class="row"><label>X<input data-way="x" type="number" value="${Math.round(wp.x)}"></label><label>Y<input data-way="y" type="number" value="${Math.round(wp.y)}"></label></div><div class="row"><label>Travel seconds<input data-way="duration" type="number" min="0.1" step="0.1" value="${wp.duration||2}"></label><label>Pause seconds<input data-way="wait" type="number" min="0" step="0.1" value="${wp.wait??0}"></label></div><label>Travel direction<select data-way="face"><option value="auto">Automatic</option><option value="right">Right</option><option value="left">Left</option><option value="down">Down (idle sprite)</option><option value="up">Up (idle sprite)</option></select></label><div class="controls"><button id="deleteWaypoint">Remove waypoint</button></div>`:'');
 const nodeDropdown=$('waypointDropdown');if(nodeDropdown){nodeDropdown.value=String(selectedWaypoint);nodeDropdown.onchange=e=>{selectedWaypoint=Number(e.target.value);panel()};}
 if(wp){$('waypointControls').querySelector('[data-way="face"]').value=wp.face||'auto';$('waypointControls').querySelectorAll('[data-way]').forEach(el=>el.onchange=()=>{checkpoint();wp[el.dataset.way]=el.dataset.way==='face'?el.value:Number(el.value);resetNpcRuntime();panel()});$('deleteWaypoint').onclick=()=>{checkpoint();p.splice(selectedWaypoint,1);selectedWaypoint=-1;resetNpcRuntime();panel()}}
 }
 if($('characterFront'))$('characterFront').onclick=()=>{checkpoint();selected.zIndex=(selected.zIndex||0)+1;panel()};
 if($('characterBack'))$('characterBack').onclick=()=>{checkpoint();selected.zIndex=(selected.zIndex||0)-1;panel()};
 options.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('on',tool===b.dataset.tool);b.onclick=()=>setTool(b.dataset.tool)});
 if($('addCharacter'))$('addCharacter').onclick=()=>{checkpoint();const ch={id:makeId('npc'),label:'New NPC',x:950,y:1000,face:'down',visible:true,sprite:'placeholder',movable:false,zIndex:0,posture:'standing',sitFace:'down'};characters.push(ch);selected=ch;panel()};
 options.querySelectorAll('[data-field]').forEach(el=>{if(['trigger','action','face'].includes(el.dataset.field))el.value=selected[el.dataset.field]||el.value;el.onchange=()=>{checkpoint();const f=el.dataset.field,v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(f==='hasApproach'){if(v&&!selected.approach){const s=selected.click;const pts=shapePoints(s);const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);selected.approach={shape:'rectangle',x:Math.min(...xs)-70,y:Math.max(...ys)+8,w:Math.max(...xs)-Math.min(...xs)+140,h:110};}else if(!v)selected.approach=null;}else{const oldX=selected.x,oldY=selected.y;selected[f]=v;if(mode==='furniture'&&(['x','y'].includes(f)))shiftLinked(selected,(selected.x??oldX)-oldX,(selected.y??oldY)-oldY);if(mode==='character'&&selected.id==='visitor')syncSpawn();}panel()}});
 if($('contentEditor'))$('contentEditor').onchange=e=>{checkpoint();selected.content=e.target.value};
 if($('deleteZone'))$('deleteZone').onclick=()=>{checkpoint();if(mode==='collision')collisions=collisions.filter(o=>o!==selected);if(mode==='interaction')interactions=interactions.filter(o=>o!==selected);if(mode==='character'){const sid=selected.sprite?.startsWith('sheet:')?selected.sprite.slice(6):null;characters=characters.filter(o=>o!==selected);if(sid&&!characters.some(c=>c.sprite==='sheet:'+sid)){delete customCharacterSheets[sid];delete images['sprite-'+sid];delete npcRuntime[selected.id]}if(selected.sprite?.startsWith('frames:')){const cid=selected.sprite.slice(7);if(!characters.some(c=>c.sprite==='frames:'+cid)){for(const key of Object.keys(customCharacterFrames[cid]?.files||{}))delete images['frames-'+cid+'-'+key];delete customCharacterFrames[cid];delete npcRuntime[selected.id]}}}selected=null;panel();};
 if($('bringFront'))$('bringFront').onclick=()=>{checkpoint();selected.zIndex=(selected.zIndex||0)+1;panel()};
 if($('sendBack'))$('sendBack').onclick=()=>{checkpoint();selected.zIndex=(selected.zIndex||0)-1;panel()};
 if($('lockFurniture'))$('lockFurniture').onclick=()=>{checkpoint();selected.locked=!selected.locked;panel()};
 if($('editClickZone'))$('editClickZone').onclick=()=>{tool='select';activeInteractionPart='click';panel()};
