function completeShape(s){if(mode==='collision'){const c={id:makeId('collision'),label:'Blocked area',enabled:true,linkedTo:'',...s};checkpoint();collisions.push(c);selected=c;}else if(mode==='interaction'){const z={id:makeId('hotspot'),label:'New interaction',prompt:'Press Space to interact',trigger:'both',action:'placeholder',content:'Coming soon',linkedTo:'',click:s,approach:(()=>{const pts=shapePoints(s),xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);return {shape:'rectangle',x:Math.min(...xs),y:Math.max(...ys)+16,w:Math.max(160,Math.max(...xs)-Math.min(...xs)),h:110}})()};checkpoint();interactions.push(z);selected=z;}tool='select';panel()}
