 if(handleHit){checkpoint();canvas.setPointerCapture(e.pointerId);const sh=handleHit.shape;drag={type:'resize',shape:sh,handle:handleHit.handle,original:sh.shape==='polygon'?null:{x:sh.x,y:sh.y,w:sh.w,h:sh.h},pointerId:e.pointerId};canvas.style.cursor='grabbing';return;}
 const o=pickZone(p);selected=o;
