 if(testMode){const p=point(e);hoveredHotspot=hitClick(p)||null;hoverPointer=hoveredHotspot?p:null;canvas.style.cursor=hoveredHotspot?interactionCursor:'default';return;}
 const p=point(e);if(drag?.type==='waypoint'){const w=drag.character.path.waypoints[drag.index];if(w){w.x=p.x;w.y=p.y;resetNpcRuntime();}return;}if(drag?.type==='drawRect'){drag.shape=newShape(drag.start,p,tool);return}if(drag?.type==='polygon'){drag.cursor=p;return}if(drag?.type==='resize'){updateResize(drag,p);return}if(drag?.type==='move'){const dx=p.x-drag.last.x,dy=p.y-drag.last.y;drag.last=p;const o=drag.object;if(mode==='furniture'){o.x+=dx;o.y+=dy;if(Number.isFinite(o.baseY))o.baseY+=dy;shiftLinked(o,dx,dy)}else if(mode==='character'){o.x+=dx;o.y+=dy;if(o.id==='visitor')syncSpawn();else resetNpcRuntime()}else if(mode==='collision')moveShape(o,dx,dy);else if(mode==='interaction'){if(drag.part==='click')moveShape(o.click,dx,dy);else if(drag.part==='approach'&&o.approach)moveShape(o.approach,dx,dy);else{moveShape(o.click,dx,dy);if(o.approach)moveShape(o.approach,dx,dy)}}return}
