function exportLevel(){return {game:'Amber Portfolio Cafe',version:4,canvas:{width:1874,height:1398},furniture:objects.map(o=>({...o})),customAssets:{...customAssets},customCharacterSheets:structuredClone(customCharacterSheets),customCharacterFrames:structuredClone(customCharacterFrames),collisions:structuredClone(collisions),interactions:structuredClone(interactions),characters:structuredClone(characters)}}
function download(name,text,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:mime}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
// The latest user-saved level is stored in IndexedDB, not localStorage: uploaded PNGs can be large.
const LEVEL_SAVE_DB='amber-cafe-v36-menu-side-quests-sandbox';
const LEVEL_SAVE_STORE='saves';
const LEVEL_SAVE_KEY='latest';
let lastSaveInfo=null;
function openLevelSaveDB(){
 return new Promise((resolve,reject)=>{
  if(!('indexedDB' in window)){reject(Error('This browser does not support local saves. Use Download level JSON instead.'));return;}
  const req=indexedDB.open(LEVEL_SAVE_DB,1);
  req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains(LEVEL_SAVE_STORE))db.createObjectStore(LEVEL_SAVE_STORE)};
  req.onsuccess=()=>resolve(req.result);
  req.onerror=()=>reject(req.error||Error('Browser save storage is unavailable'));
 });
}
async function readLevelSave(){
 const db=await openLevelSaveDB();
 try{return await new Promise((resolve,reject)=>{const req=db.transaction(LEVEL_SAVE_STORE,'readonly').objectStore(LEVEL_SAVE_STORE).get(LEVEL_SAVE_KEY);req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error||Error('Could not read your save'));});}
 finally{db.close()}
}
async function writeLevelSave(payload){
 const db=await openLevelSaveDB();
 try{await new Promise((resolve,reject)=>{const tx=db.transaction(LEVEL_SAVE_STORE,'readwrite');tx.objectStore(LEVEL_SAVE_STORE).put(payload,LEVEL_SAVE_KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('Browser storage is full or disabled'));tx.onabort=()=>reject(tx.error||Error('Browser save was cancelled'));});}
 finally{db.close()}
}
function formatSaveTime(ts){return new Date(ts).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})}
function setSaveInfo(msg){const el=$('saveInfo');if(el)el.textContent=msg}
$('saveButton').onclick=async()=>{
 const button=$('saveButton');button.disabled=true;button.textContent='Saving…';
 try{
  const savedAt=Date.now();await writeLevelSave({savedAt,layout:exportLevel()});lastSaveInfo=savedAt;
  setSaveInfo('Saved in this browser: '+formatSaveTime(savedAt)+'. Reopening this editor will restore it automatically.');
  summary('Saved! Your latest layout, PNG furniture, and character images are remembered in this browser.');
 }catch(err){setSaveInfo('Save failed: '+err.message+'. Download level JSON for a backup.');summary('Save failed: '+err.message)}
 finally{button.disabled=false;button.textContent='💾 Save'}
};
async function loadLatestBrowserSave(){
 try{
  const entry=await readLevelSave();
  if(!entry?.layout)return false;
  if(entry.layout.canvas?.width!==1874||entry.layout.canvas?.height!==1398||!Array.isArray(entry.layout.furniture))throw Error('Saved layout is not compatible');
  await restoreAsync(entry.layout);
  history=[];future=[];lastSaveInfo=entry.savedAt||null;
  setSaveInfo('Restored browser save from '+formatSaveTime(entry.savedAt||Date.now())+'. Click Save after making more changes.');
  summary('Restored your most recent browser save.');
  return true;
 }catch(err){setSaveInfo('Could not restore browser save: '+err.message+'. You can still import a JSON backup.');return false}
}

