window.addEventListener('keydown',e=>{if(!document.getElementById('musicModal').hidden){keys.clear();musicKeydown(e);return;}if(!$('modal').hidden){keys.clear();if(e.key==='Escape')closeDialog();return}if(cafeAnyModalOpen()){keys.clear();return;}if((e.target instanceof HTMLInputElement)||(e.target instanceof HTMLSelectElement)||(e.target instanceof HTMLTextAreaElement))return;
 const k=e.key.toLowerCase();if((e.metaKey||e.ctrlKey)&&k==='z'){e.preventDefault();e.shiftKey?redo():undo();return}
 if(!testMode){if(k==='enter'&&drag?.type==='polygon'){if(drag.points.length>=3)completeShape({shape:'polygon',points:drag.points});drag=null;return}if(k==='escape'){drag=null;selected=null;tool='select';panel();return}const d={arrowleft:[-1,0],arrowright:[1,0],arrowup:[0,-1],arrowdown:[0,1]}[k];if(d&&selected){e.preventDefault();checkpoint();const dx=d[0]*(e.shiftKey?10:1),dy=d[1]*(e.shiftKey?10:1);if(mode==='furniture'&&!selected.locked){selected.x+=dx;selected.y+=dy;selected.baseY+=dy;shiftLinked(selected,dx,dy)}else if(mode==='character'){selected.x+=dx;selected.y+=dy;syncSpawn()}else if(mode==='collision')moveShape(selected,dx,dy);else if(mode==='interaction'){moveShape(selected.click,dx,dy);if(selected.approach)moveShape(selected.approach,dx,dy)}panel()}return}
 if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){keys.add(k);e.preventDefault()}else if(k===' '){e.preventDefault();trigger(nearby())}
});
