// Accessible music library. Audio element deliberately lives outside dialog; closing dialog never pauses it.
const MUSIC_TRACKS=[{"title":"21st Century People","file":"21st Century People.mp3"},{"title":"Amazing Everyday","file":"Amazing Everyday.mp3"},{"title":"Asphalt","file":"Asphalt.mp3"},{"title":"Cherry Blossom Season","file":"Cherry Blossom Season.mp3"},{"title":"Confession","file":"Confession.mp3"},{"title":"First Snow","file":"First Snow.mp3"},{"title":"Fresh Wreath","file":"Fresh Wreath.mp3"},{"title":"Go Go go Summer","file":"Go Go go Summer.mp3"},{"title":"Hanging out in Tokyo","file":"Hanging out in Tokyo.mp3"},{"title":"Inorimichite","file":"Inorimichite.mp3"},{"title":"Lonely Journey","file":"Lonely Journey.mp3"},{"title":"Muscat and White Dishes","file":"Muscat and White Dishes.mp3"},{"title":"Piercing Wind","file":"Piercing Wind.mp3"},{"title":"Prism","file":"Prism.mp3"},{"title":"Rainbow of the Night","file":"Rainbow of the Night.mp3"},{"title":"Step on the Scarlet Soil","file":"Step on the Scarlet Soil.mp3"},{"title":"Summer Sky and Homework","file":"Summer Sky and Homework.mp3"},{"title":"Wind Trail","file":"Wind Trail.mp3"},{"title":"Winter Satellite","file":"Winter Satellite.mp3"}];
const musicAudio=document.getElementById('cafeMusicAudio');
// Start music at 15% volume by default.
musicAudio.volume=0.15;
const cafeVolumeSlider=document.getElementById('cafeMusicVolume');
const cafeVolumeValue=document.getElementById('cafeMusicVolumeValue');
cafeVolumeSlider.addEventListener('input',()=>{const level=Number(cafeVolumeSlider.value);musicAudio.volume=level/100;cafeVolumeValue.textContent=level+'%';});
let currentTrack=-1, musicResumeTarget=null;
// Music is loaded on demand; tracks are no longer embedded into startup JavaScript.
const EMBEDDED_MUSIC=Object.fromEntries(MUSIC_TRACKS.map(t=>[t.file,'assets/music/'+encodeURIComponent(t.file)]));
const songUrl=(track)=>EMBEDDED_MUSIC[track.file];
function randomTrack(){if(MUSIC_TRACKS.length===1)return 0;let n=Math.floor(Math.random()*MUSIC_TRACKS.length);if(n===currentTrack)n=(n+1+Math.floor(Math.random()*(MUSIC_TRACKS.length-1)))%MUSIC_TRACKS.length;return n;}
function cafeMusicFilledIcon(name){
 const shapes={
  play:'<path d="M8 5.14v13.72c0 .76.83 1.24 1.5.86l10.29-6.86a1.04 1.04 0 0 0 0-1.72L9.5 4.28C8.83 3.9 8 4.38 8 5.14Z"/>',
  pause:'<path d="M6 4h4v16H6zm8 0h4v16h-4z"/>',
  next:'<path d="M5 5.55v12.9c0 .63.7 1 1.22.66L15 13.4V19h3V5h-3v5.6L6.22 4.89A.8.8 0 0 0 5 5.55Z"/>',
  shuffle:'<path d="M10.59 9.17 5.41 4 4 5.41l5.17 5.18 1.42-1.42ZM14.5 4l2.04 2.04L4 18.59 5.41 20 17.96 7.46 20 9.5V4h-5.5ZM14.83 13.41l-1.42 1.42 3.13 3.13L14.5 20H20v-5.5l-2.04 2.04-3.13-3.13Z"/>',
  refresh:'<path d="M17.65 6.35A7.95 7.95 0 0 0 12 4a8 8 0 1 0 7.93 9h-2.02A6 6 0 1 1 12 6c1.66 0 3.14.69 4.22 1.78L13 11h7V4l-2.35 2.35Z"/>',
  music:'<path d="M12 3v11.55A4 4 0 1 1 10 11V5.2L21 3v10.55A4 4 0 1 1 19 10V1.5L12 3Z"/>'
 };
 return '<svg class="cafe-music-filled-icon" viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true">'+(shapes[name]||shapes.play)+'</svg>';
}
function musicStatus(){const playing=!musicAudio.paused&&!musicAudio.ended;document.getElementById('musicPlayPause').innerHTML=cafeMusicFilledIcon(playing?'pause':'play')+'<span>'+(playing?'Pause':'Play')+'</span>';document.getElementById('musicPlayPause').setAttribute('aria-label',playing?'Pause music':'Play music');document.getElementById('musicNowPlaying').textContent=currentTrack<0?'Choose a song to start the music.':(playing?'Now playing: ':'Paused: ')+MUSIC_TRACKS[currentTrack].title;
 const dur=Number.isFinite(musicAudio.duration)?musicAudio.duration:0;const time=Number.isFinite(musicAudio.currentTime)?musicAudio.currentTime:0;const fmt=x=>`${Math.floor(x/60)}:${String(Math.floor(x%60)).padStart(2,'0')}`;document.getElementById('musicProgress').textContent=currentTrack<0?'—':fmt(time)+' / '+(dur?fmt(dur):'—');
 document.querySelectorAll('.music-track').forEach(el=>{const i=Number(el.dataset.track);el.setAttribute('aria-current',String(i===currentTrack));el.querySelector('.playglyph').innerHTML=cafeMusicFilledIcon(i===currentTrack&&playing?'music':'play');});
}
function chooseMusic(index){if(index===-1)index=randomTrack();if(index<0||index>=MUSIC_TRACKS.length)return;currentTrack=index;musicAudio.src=songUrl(MUSIC_TRACKS[index]);musicAudio.load();const promise=musicAudio.play();if(promise?.catch)promise.catch(()=>{document.getElementById('musicNowPlaying').textContent='Playback blocked or file unavailable. Use Play to retry.'});musicStatus();}
function toggleMusic(){if(currentTrack<0){chooseMusic(randomTrack());return;}if(musicAudio.paused){const p=musicAudio.play();if(p?.catch)p.catch(()=>{});}else musicAudio.pause();musicStatus();}
function openMusic(){if(!document.getElementById('modal').hidden)closeDialog();musicResumeTarget=document.activeElement;keys.clear();const modal=document.getElementById('musicModal');modal.hidden=false;musicStatus();document.querySelector('.music-track')?.focus({preventScroll:true});}
function closeMusic(){document.getElementById('musicModal').hidden=true;keys.clear();if(musicResumeTarget&&musicResumeTarget.isConnected)musicResumeTarget.focus();else canvas.focus();}
function musicKeydown(e){if(e.key==='Escape'){e.preventDefault();closeMusic();return;}const modal=document.getElementById('musicModal');const controls=[...modal.querySelectorAll('button:not([disabled])')];const focusIndex=controls.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const songs=[...document.querySelectorAll('.music-track')];let at=songs.indexOf(document.activeElement);at=at<0?(e.key==='ArrowDown'?0:songs.length-1):(at+(e.key==='ArrowDown'?1:-1)+songs.length)%songs.length;songs[at]?.focus();}else if(e.key==='Tab'&&controls.length){const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
function buildMusicList(){const parent=document.getElementById('musicList');const all=MUSIC_TRACKS.map((t,index)=>({title:t.title,index}));parent.replaceChildren();for(const t of all){const b=document.createElement('button');b.type='button';b.className='music-track';b.dataset.track=String(t.index);b.setAttribute('aria-label',t.index===-1?'Play a random song':'Play '+t.title);b.innerHTML='<span class="playglyph" aria-hidden="true">'+cafeMusicFilledIcon('play')+'</span><span></span>';b.lastChild.textContent=t.title;b.onclick=()=>chooseMusic(t.index);parent.appendChild(b)}musicStatus()}
document.getElementById('musicClose').onclick=closeMusic;
document.getElementById('musicPlayPause').onclick=toggleMusic;
document.getElementById('musicNext').innerHTML=cafeMusicFilledIcon('refresh')+'<span>Random</span>';
document.getElementById('musicNext').onclick=()=>chooseMusic(randomTrack());
musicAudio.addEventListener('ended',()=>chooseMusic(randomTrack()));
musicAudio.addEventListener('play',musicStatus);musicAudio.addEventListener('pause',musicStatus);musicAudio.addEventListener('loadedmetadata',musicStatus);
musicAudio.addEventListener('timeupdate',()=>{if(!document.getElementById('musicModal').hidden)musicStatus()});
musicAudio.addEventListener('error',()=>{document.getElementById('musicNowPlaying').textContent='Audio could not be loaded. Make sure the music folder is beside index.html.'});
