const applyImportedSave=()=>{
  const byId=new Map(objects.map(o=>[o.id,o]));
  for(const item of IMPORTED_SAVE.furniture){const target=byId.get(item.id);if(target && target.asset===item.asset)Object.assign(target,item);}
  collisions=structuredClone(IMPORTED_SAVE.collisions||[]);
  interactions=structuredClone(IMPORTED_SAVE.interactions||[]);
  characters=structuredClone(IMPORTED_SAVE.characters||defaultChars).map(normalizeCharacter);
  history=[];future=[];selected=null;syncSpawn();resetNpcRuntime();
};
(async()=>{
  window.cafeLoadProgress?.(22,'Preparing the café…');
  const allAssets=Object.entries(ASSETS),total=allAssets.length;
  let loaded=0;
  await Promise.all(allAssets.map(([name,src])=>new Promise((resolve,reject)=>{
    const im=new Image();im.onload=()=>{images[name]=im;loaded++;window.cafeLoadProgress?.(22+Math.round(43*loaded/total),'Preparing the café…');resolve()};
    im.onerror=()=>reject(Error(name));im.src=src;
  })));
  window.cafeLoadProgress?.(70,'Setting things up…');
  ready=true;await restoreAsync(IMPORTED_SAVE);
  window.cafeLoadProgress?.(88,'Restoring your café…');
  history=[];future=[];await loadLatestBrowserSave();
  // V85: enter playable game immediately; retain hidden editor controls for initialization.
  setTest(true);
  render();requestAnimationFrame(frame);
  window.cafeLoadComplete?.();
})().catch(e=>{window.cafeLoadError?.(e.message);summary('Asset load problem: '+e.message)});
